using System;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using Mono.Cecil;using Mono.Cecil.Cil;
class ComparePaths{static IEnumerable<TypeDefinition> Types(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var x in Types(n))yield return x;}static string C(Instruction i,List<Instruction> list){object op=i.Operand;var target=op as Instruction;var targets=op as Instruction[];return i.OpCode+" "+(target!=null?"target"+list.IndexOf(target):targets!=null?String.Join(",",targets.Select(t=>list.IndexOf(t))):Convert.ToString(op));}static string H(byte[] b){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b));}static void Main(string[] a){using(var o=AssemblyDefinition.ReadAssembly(a[0]))using(var p=AssemblyDefinition.ReadAssembly(a[1])){if(o.Name.FullName!=p.Name.FullName||o.MainModule.Mvid!=p.MainModule.Mvid)throw new Exception("Identity changed");var ot=o.MainModule.Types.SelectMany(Types).ToArray();var pt=p.MainModule.Types.SelectMany(Types).ToArray();if(ot.Length!=pt.Length)throw new Exception("Type count");int edits=0,added=0,methods=0,instructions=0;for(int t=0;t<ot.Length;t++){if(ot[t].FullName!=pt[t].FullName||ot[t].Fields.Count!=pt[t].Fields.Count||ot[t].Methods.Count!=pt[t].Methods.Count)throw new Exception("Structure changed");for(int m=0;m<ot[t].Methods.Count;m++){var x=ot[t].Methods[m];var y=pt[t].Methods[m];if(x.FullName!=y.FullName||x.HasBody!=y.HasBody)throw new Exception("Signature changed");methods++;if(!x.HasBody)continue;var original=x.Body.Instructions.ToList();var patched=y.Body.Instructions.ToList();int add=patched.RemoveAll(ins=>ins.Operand is MethodReference&&((MethodReference)ins.Operand).FullName=="System.String TCG.NativeCompatibility.PathLiterals::Select(System.String)");if(add>0&&!(x.DeclaringType.FullName=="TextureReplacer.BepInExPlugin"&&(x.Name=="CacheCardDataAtStart"||x.Name=="LoadCardNames")))throw new Exception("Unexpected helper site");added+=add;if(original.Count!=patched.Count||x.Body.ExceptionHandlers.Count!=y.Body.ExceptionHandlers.Count)throw new Exception("Body structure changed");for(int n=0;n<x.Body.Instructions.Count;n++){instructions++;var i=original[n];var j=patched[n];if(C(i,original)==C(j,patched))continue;var mr=j.Operand as MethodReference;if(mr==null||mr.FullName!="System.String TCG.NativeCompatibility.PathLiterals::PrepatchDataBase(System.String,System.String)"||x.FullName!="System.Void EnhancedPrefabLoader.Prepatch.PatchDataManager::.cctor()")throw new Exception("Unexpected IL difference "+x.FullName+" "+i+" => "+j);edits++;}}}bool texture=o.Name.Name=="TextureReplacer";if(texture?(added!=5||edits!=0):(added!=0||edits!=1))throw new Exception("Unexpected edit counts");if(o.MainModule.Resources.Count!=p.MainModule.Resources.Count)throw new Exception("Resource count");for(int i=0;i<o.MainModule.Resources.Count;i++){var x=o.MainModule.Resources[i];var y=p.MainModule.Resources[i];if(x.Name!=y.Name)throw new Exception("Resource name");if(x is EmbeddedResource&&H(((EmbeddedResource)x).GetResourceData())!=H(((EmbeddedResource)y).GetResourceData()))throw new Exception("Resource content changed");}Console.WriteLine("Verified "+methods+" methods / "+instructions+" instructions; "+added+" literal dispatch additions / "+edits+" save-root substitutions, assembly identity/MVID/resources preserved");}}}
